-- Values that Python's datetime can't represent, such as BC dates and infinity, are cast to VARCHAR.

# name: date_input_formats
SELECT DATE 'January 8, 1999', DATE '1999-01-08', DATE '1/8/1999', DATE '1/18/1999', DATE '01/02/03', DATE '1999-Jan-08', DATE 'Jan-08-1999', DATE '08-Jan-1999', DATE '08-Jan-99', DATE 'Jan-08-99', DATE '19990108', DATE '990108', DATE '1999.008', DATE 'J2451187', CAST(DATE 'January 8, 99 BC' AS VARCHAR);

# name: date_cast_and_compare
SELECT id, CAST(CAST(v_date AS VARCHAR) AS DATE), v_date < DATE '2000-01-01', v_date = DATE 'epoch' FROM scalars ORDER BY id;

# name: special_values
SELECT DATE 'epoch', TIMESTAMP 'epoch', TIMESTAMPTZ 'epoch', TIME 'allballs', CAST(TIMESTAMP 'infinity' AS VARCHAR), CAST(TIMESTAMP '-infinity' AS VARCHAR), TIMESTAMP 'infinity' > TIMESTAMP '9999-12-31', TIMESTAMP '-infinity' < TIMESTAMP '0001-01-01';

# name: special_relative_values
SELECT DATE 'today' = CURRENT_DATE, TIMESTAMP 'today' = CURRENT_DATE, DATE 'tomorrow' = CURRENT_DATE + 1, TIMESTAMP 'yesterday' = CURRENT_DATE - 1, TIMESTAMP 'NOW' > TIMESTAMP '2020-01-01', DATE 'NOW' = CURRENT_DATE, TIME 'NOW' IS NOT NULL;

# name: special_values_against_columns
SELECT id, v_ts < TIMESTAMP 'infinity', v_ts > TIMESTAMP '-infinity', v_date >= DATE 'epoch' FROM scalars ORDER BY id;

# name: month_names
SELECT DATE 'JANUARY 1 2020', DATE 'JAN 2 2020', DATE 'FEBRUARY 3 2020', DATE 'FEB 4 2020', DATE 'MARCH 5 2020', DATE 'MAR 6 2020', DATE 'APRIL 7 2020', DATE 'APR 8 2020', DATE 'MAY 9 2020', DATE 'JUNE 10 2020', DATE 'JUN 11 2020', DATE 'JULY 12 2020', DATE 'JUL 13 2020', DATE 'AUGUST 14 2020', DATE 'AUG 15 2020', DATE 'SEPTEMBER 16 2020', DATE 'SEP 17 2020', DATE 'SEPT 18 2020', DATE 'OCTOBER 19 2020', DATE 'OCT 20 2020', DATE 'NOVEMBER 21 2020', DATE 'NOV 22 2020', DATE 'DECEMBER 23 2020', DATE 'DEC 24 2020';

# name: day_of_week_names
SELECT DATE 'SUNDAY January 5 2020', DATE 'SUN January 5 2020', DATE 'MONDAY January 6 2020', DATE 'MON January 6 2020', DATE 'TUESDAY January 7 2020', DATE 'TUE January 7 2020', DATE 'TUES January 7 2020', DATE 'WEDNESDAY January 8 2020', DATE 'WED January 8 2020', DATE 'WEDS January 8 2020', DATE 'THURSDAY January 9 2020', DATE 'THU January 9 2020', DATE 'THUR January 9 2020', DATE 'THURS January 9 2020', DATE 'FRIDAY January 10 2020', DATE 'FRI January 10 2020', DATE 'SATURDAY January 11 2020', DATE 'SAT January 11 2020';

# name: time_zone_values
SELECT TIMESTAMPTZ '1999-01-08 04:05:06 PST', TIMESTAMPTZ '1999-01-08 04:05:06 -8:00', TIMESTAMPTZ '1999-01-08 04:05:06 -800', TIMESTAMPTZ '1999-01-08 04:05:06 -8', TIMESTAMPTZ '1999-01-08 04:05:06 zulu', TIMESTAMPTZ '1999-01-08 04:05:06 z', TIMESTAMPTZ '1999-01-08 04:05:06 America/Chicago', TIMESTAMPTZ '2017-07-01 04:05:06 America/Chicago';

# name: time_zone_values_at_time_zone
SELECT id, v_tstz AT TIME ZONE 'PST', v_tstz AT TIME ZONE 'zulu', v_tstz AT TIME ZONE 'z', v_tstz AT TIME ZONE INTERVAL '-08:00', v_tstz AT TIMEZONE 'America/Denver' FROM scalars WHERE v_tstz BETWEEN TIMESTAMPTZ '1900-01-01 00:00:00+00' AND TIMESTAMPTZ '2100-01-01 00:00:00+00' ORDER BY id;

# name: timestamp_literals
SELECT TIMESTAMP '1999-01-08 04:05:06', TIMESTAMP(3) '2020-01-01 10:00:00.123456', TIMESTAMP(0) '2020-01-01 10:00:00.5', TIMESTAMPTZ(2) '2020-01-01 10:00:00.12345+02', TIMESTAMP WITH TIME ZONE '1999-01-08 04:05:06 -8:00', TIMESTAMP WITHOUT TIME ZONE '1999-01-08 04:05:06', TIMESTAMP 'January 8 04:05:06 1999', DATETIME '1999-01-08 04:05:06', SMALLDATETIME '1999-01-08 04:05:06';

# name: timestamp_literals_with_zone_in_string
SELECT TIMESTAMP '1999-01-08 04:05:06 -8:00', TIMESTAMP 'January 8 04:05:06 1999 PST', TIMESTAMP WITHOUT TIME ZONE '2020-01-01 10:00+05', TIMESTAMP '2001-02-16 20:38:40 America/Mexico_City' AT TIME ZONE 'Asia/Tokyo', CAST('2020-01-01 10:00+05' AS TIMESTAMP), '2020-01-01 10:00+05'::TIMESTAMP;

# name: timestamp_era
SELECT CAST(TIMESTAMP WITH TIME ZONE 'March 1, 44 12:00 CET BC ' AS VARCHAR), CAST(TIMESTAMP WITH TIME ZONE 'March 1, 44 12:00 BC CET' AS VARCHAR), TIMESTAMP '2020-01-01 10:00 AD', CAST(TIMESTAMP '0044-03-01 12:00 BC' AS VARCHAR);

# name: timestamp_at_time_zone
SELECT TIMESTAMP '2017-3-14 5:30' AT TIME ZONE 'PDT', TIMESTAMP WITH TIME ZONE '2001-02-16 20:38:40' AT TIME ZONE 'America/Denver', TIMESTAMPTZ '2017-03-16 09:56:13' AT TIME ZONE 'America/Denver', TIMESTAMPTZ '2017-03-16 09:56:13' AT TIME ZONE INTERVAL '-06:00', TIMESTAMPTZ '2017-01-16 09:56:13' AT TIMEZONE INTERVAL '-06:00', TIMESTAMP '2017-01-16 09:56:13' AT TIME ZONE 'America/Denver' AT TIME ZONE 'Asia/Tokyo';

# name: timestamp_column_at_time_zone
SELECT id, v_ts AT TIME ZONE 'PDT', v_ts AT TIMEZONE INTERVAL '05:30', v_tstz AT TIME ZONE INTERVAL '-06:00' FROM scalars WHERE v_ts BETWEEN TIMESTAMP '1900-01-01' AND TIMESTAMP '2100-01-01' ORDER BY id;

# name: timestamp_arithmetic
SELECT (TIMESTAMP '2014-01-17 10:00' - TIMESTAMP '2014-01-01'), (TIMESTAMP '2014-01-17 10:00' - TIMESTAMP '2014-01-01') / 7, TIMESTAMP '2009-05-29 15:21:00.456789' - TIMESTAMP '2009-05-28', (TIMESTAMP '2009-05-29 15:21:00.456789' - TIMESTAMP '2009-05-28')(3), '2017-03-18 07:00'::TIMESTAMPTZ(0) + INTERVAL '1.5 day', FLOOR((TIMESTAMP '2014-01-17 10:00' - TIMESTAMP '2014-01-01') / INTERVAL '7');

# name: timestamp_difference_qualifiers
SELECT (TIMESTAMP '2014-01-17 10:00' - TIMESTAMP '2014-01-01') DAY, CAST((TIMESTAMP '2014-01-17 10:00' - TIMESTAMP '2014-01-01') DAY AS INTEGER) / 7, (TIMESTAMP '2009-05-29 15:21:00.456789' - TIMESTAMP '2009-05-28') SECOND, (TIMESTAMP '2012-05-29 15:21:00.456789' - TIMESTAMP '2009-01-01') YEAR, (TIMESTAMP '2012-05-29 15:21:00.456789' - TIMESTAMP '2009-01-01') MONTH, (TIMESTAMP '2012-05-29 15:21:00.456789' - TIMESTAMP '2009-01-01') YEAR TO MONTH, (TIMESTAMP '2012-05-29 15:21:00.456789' - TIMESTAMP '2009-01-01') SECOND(3), (TIMESTAMP '2012-05-29 15:21:00.456789' - TIMESTAMP '2009-01-01') MINUTE, (TIMESTAMP '2012-05-29 15:21:00.456789' - TIMESTAMP '2009-01-01') MINUTE TO SECOND(3);

# name: timestamp_difference_qualifiers_text
SELECT CAST((TIMESTAMP '2009-05-29 15:21:00.456789' - TIMESTAMP '2009-05-28')(3) AS VARCHAR), CAST((TIMESTAMP '2012-05-29 15:21:00.456789' - TIMESTAMP '2009-01-01') MINUTE TO SECOND(3) AS VARCHAR), CAST((TIMESTAMP '2014-01-17 10:00' - TIMESTAMP '2014-01-01') DAY AS VARCHAR), CAST((TIMESTAMP '2012-05-29 15:21:00.456789' - TIMESTAMP '2009-01-01') YEAR TO MONTH AS VARCHAR);

# name: timestamp_difference_qualifiers_columns
SELECT id, (v_ts - TIMESTAMP '2000-01-01') DAY, (v_ts - TIMESTAMP '2000-01-01') YEAR TO MONTH, (v_tstz - TIMESTAMPTZ '2000-01-01 00:00:00+00') MONTH, (v_ts - TIMESTAMP '2000-01-01')(0), (v_ts - TIMESTAMP '2000-01-01') HOUR TO MINUTE FROM scalars WHERE v_ts BETWEEN TIMESTAMP '1900-01-01' AND TIMESTAMP '2100-01-01' ORDER BY id;

# name: timestamp_precision_casts
SELECT id, CAST(v_ts AS TIMESTAMP(0)), CAST(v_ts AS TIMESTAMP(3)), CAST(v_tstz AS TIMESTAMPTZ(1)), v_ts::DATETIME, v_ts::SMALLDATETIME FROM scalars WHERE v_ts BETWEEN TIMESTAMP '1900-01-01' AND TIMESTAMP '2100-01-01' ORDER BY id;

# name: time_literals
SELECT TIME '04:05:06.789', TIME '04:05:06', TIME '04:05', TIME '040506', TIME '04:05 AM', TIME '04:05 PM', TIME(2) '10:00:00.12345', TIME(0) '10:00:00.5', TIME WITHOUT TIME ZONE '04:05:06';

# name: time_literals_with_zone
SELECT TIME '04:05:06.789-8', TIME '04:05:06-08:00', TIME '04:05-08:00', TIME '040506-08', TIME '04:05:06 PST', TIME WITH TIME ZONE '04:05:06-08:00', TIMETZ '14:34:06.4+6', TIMETZ(1) '14:34:06.45+6', TIME WITHOUT TIME ZONE '04:05:06-08:00', CAST('04:05:06-08:00' AS TIME);

# name: time_at_time_zone
SELECT TIME '10:10:56' AT TIME ZONE 'America/Denver', TIME '09:56:13 Europe/Vilnius' AT TIME ZONE 'America/Denver', TIME '10:10:56' AT TIME ZONE INTERVAL '-06:00', TIME WITH TIME ZONE '10:10:56+02' AT TIMEZONE 'UTC', TIMETZ '10:30+13:30' AT TIME ZONE 'UTC';

# name: time_column
SELECT id, v_time, CAST(CAST(v_time AS TIME(0)) AS VARCHAR), CAST(v_time AS TIMETZ), v_time AT TIME ZONE 'America/Denver', CAST(v_time AS VARCHAR) FROM vertica_extras ORDER BY id;

# name: time_coercion
SELECT CAST(CAST(TIME '3:01am' AS TIMESTAMP) AS TIME), CAST(TIME '3:01am' AS TIMESTAMP) = CURRENT_DATE + TIME '3:01am', (TIMETZ '3:01am')::TIMESTAMP = CURRENT_DATE + TIME '3:01am', CAST((TIME '3:01am')::TIMESTAMPTZ AS TIME);

# name: timetz_extract
SELECT EXTRACT(TIMEZONE_HOUR FROM TIMETZ '10:30+13:30'), EXTRACT(TIMEZONE_MINUTE FROM TIMETZ '10:30+13:30'), EXTRACT(HOUR FROM TIMETZ '10:30+13:30'), EXTRACT(TIMEZONE_HOUR FROM TIMESTAMPTZ '2020-01-01 10:30+05');

# name: datetime_operators
SELECT DATE '2001-09-28' + INTEGER '7', 7 + DATE '2001-09-28', DATE '2001-09-28' + INTERVAL '1 HOUR', DATE '2001-09-28' + TIME '03:00', TIME '03:00' + DATE '2001-09-28', INTERVAL '1 DAY' + INTERVAL '1 HOUR', TIMESTAMP '2001-09-28 01:00' + INTERVAL '23 HOURS', TIME '01:00' + INTERVAL '3 HOURS', - INTERVAL '23 HOURS';

# name: datetime_operators_subtraction
SELECT DATE '2001-10-01' - DATE '2001-09-28', DATE '2001-10-01' - INTEGER '7', DATE '2001-09-28' - INTERVAL '1 HOUR', TIME '05:00' - TIME '03:00', TIME '05:00' - INTERVAL '2 HOURS', TIMESTAMP '2001-09-28 23:00' - INTERVAL '23 HOURS', INTERVAL '1 DAY' - INTERVAL '1 HOUR', TIMESTAMP '2001-09-29 03:00' - TIMESTAMP '2001-09-27 12:00';

# name: datetime_operators_multiplication
SELECT 900 * INTERVAL '1 SECOND', 21 * INTERVAL '1 DAY', DOUBLE PRECISION '3.5' * INTERVAL '1 HOUR', INTERVAL '1 HOUR' / DOUBLE PRECISION '1.5', INTERVAL '1 HOUR' * 2.5, 2 * INTERVAL '1-6' YEAR TO MONTH;

# name: datetime_operators_columns
SELECT id, v_date + 7, v_date - 7, v_date + INTERVAL '1 HOUR', v_date - DATE '2000-01-01', v_ts - v_date, v_tstz - INTERVAL '23 HOURS', v_tstz - v_ts, v_date + TIME '03:00' FROM scalars WHERE v_date BETWEEN DATE '1900-01-01' AND DATE '2100-01-01' ORDER BY id;

# name: datetime_expressions_numbers
SELECT DATE '19990113', TIME '141516', TIMESTAMP '19990113 141516', TIMESTAMP '1999-01-13 1415', DATE '1999 013', DATE '01/02/69', DATE '01/02/70', DATE '0099-01-01';

# name: datetime_expressions_text_fields
SELECT TIMESTAMP 'Thursday, January 13 1999 04:05', TIMESTAMP 'January 13 1999 at 04:05', TIMESTAMP 'on January 13 1999 04:05:06', TIMESTAMPTZ 'January 13 1999 04:05:06 +05', CAST(DATE 'January 13, 99 BC' AS VARCHAR);
